/* Read-only visual teaching layer. Canonical scenario entries and battle records stay unchanged. */
(function(){'use strict';
const R=()=>window.RULES_DATA||{},E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko,tag='span')=>`<${tag} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</${tag}>`,P=pair=>window.MMRuleTerms?.prose(...pair,{edition:'n26'})||L(...pair,'p'),valid=r=>r?.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26';
function resolve(row,kind,options={}){if(!['scenarioEntries','sideJobs'].includes(kind)||String(options.edition||row?.edition_slug||row?.edition).toLowerCase()!=='n26'||!valid(row)||row.is_custom||row.reference_custom_description||row.reference_description_cleared)return null;const source=kind==='sideJobs'?(R().scenarioEntries||[]).find(e=>e.side_job_id===row.id):(R().scenarioEntries||[]).find(e=>e.id===row.id);if(!valid(source))return null;const key=source.id.replace(/^official-003-scenario-entry-/,'');const guide=window.MMScenarioGuideData?.[key];return guide?{source,key,guide}:null;}
const txt=(x,y,en,ko,extra='')=>`<text x="${x}" y="${y}" text-anchor="middle" ${extra} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</text>`;
function token(x,y,side,ignored=false){return `<g class="sg-token sg-side-${side.toLowerCase()}${ignored?' is-ignored':''}">${side==='A'?`<circle cx="${x}" cy="${y}" r="12"/>`:`<rect x="${x-12}" y="${y-12}" width="24" height="24" rx="3"/>`}<text x="${x}" y="${y+4}" text-anchor="middle" data-i18n-ignore>${ignored?'×':side}</text></g>`;}
const turfCases={
 a:{label:['Only A in the area','A만 있음'],a:2,b:0,round:3,result:['A wins this central condition','중앙 조건으로 A 승리'],why:['At round 3’s End-phase check, A has two qualifying models inside and B has none.','3라운드 종료 단계 승리 확인 때 원 안의 유효 모델이 A 2개·B 0개입니다.']},
 b:{label:['Only B in the area','B만 있음'],a:0,b:1,round:3,result:['B wins this central condition','중앙 조건으로 B 승리'],why:['The condition works symmetrically: B alone has a qualifying model inside.','반대로 B만 유효 모델이 있으면 B가 승리합니다.']},
 both:{label:['A 2 vs B 1','A 2개·B 1개'],a:2,b:1,round:3,result:['No central winner · continue','중앙 승리 없음 · 계속 진행'],why:['A has more models, but B still has one qualifying model inside. Both sides are present.','A가 더 많아도 B의 유효 모델 1개가 남아 있습니다. 양쪽 다 있으므로 중앙 승리가 아닙니다.']},
 injured:{label:['B’s model is injured','B가 중상인 경우'],a:1,b:0,ignored:1,round:3,result:['A wins this central condition','중앙 조건으로 A 승리'],why:['B’s only model in the circle is Seriously Injured (or Seriously Damaged), so it is ignored. Only A counts.','원 안의 B 모델이 중상(차량이라면 중손상)이므로 제외합니다. 판정에 포함되는 것은 A뿐입니다.']},
 empty:{label:['Neither in the area','원 안에 아무도 없음'],a:0,b:0,round:3,result:['No central winner · continue','중앙 승리 없음 · 계속 진행'],why:['Both sides still have models outside the circle, but neither has a qualifying model inside.','양쪽 모두 원 밖에는 모델이 남아 있지만 원 안의 유효 모델은 없습니다.']},
 early:{label:['Same position in round 2','2라운드라면?'],a:2,b:0,round:2,result:['The central check has not started','중앙 조건 확인은 아직 시작 전'],why:['This central victory condition begins in round 3. Being alone in the circle in round 2 does not satisfy that timing.','중앙 승리 조건은 3라운드부터입니다. 2라운드에 혼자 들어와 있어도 확인 시점 조건을 충족하지 않습니다.']}
};
// Coordinates use inches on a square board, projected with one uniform scale on both axes.
const boardSize=value=>Number(value)===48?48:36;
function board(inches){const n=boardSize(inches),x=42,y=42,side=336,scale=side/n;return {n,x,y,side,scale,cx:210,cy:210,end:378,at:v=>42+v*scale};}
function measuredLine(x1,y1,x2,y2,label){return `<g class="sg-measure"><path d="M${x1} ${y1}L${x2} ${y2}M${x1} ${y1-4}v8M${x2} ${y2-4}v8" class="sg-distance"/>${txt((x1+x2)/2,y1-8,label,label)}</g>`;}
function frame(body,inches=36){const b=board(inches),grid=[];for(let i=6;i<b.n;i+=6)grid.push(`<path d="M${b.at(i)} 42v336M42 ${b.at(i)}h336" class="sg-grid"/>`);const ticks=[];for(let i=0;i<=b.n;i+=6)ticks.push(`<path d="M${b.at(i)} 378v5" class="sg-distance"/>${txt(b.at(i),401,String(i),String(i),'class="sg-ruler"')}`);return `<svg viewBox="0 0 420 424" class="sg-board sg-scaled-board" role="img" aria-label="${b.n} by ${b.n} inch battlefield" data-i18n-en-aria-label="${b.n} by ${b.n} inch battlefield" data-i18n-ko-aria-label="${b.n}×${b.n}인치 전장" data-board-inches="${b.n}" data-inch-scale="${b.scale}" focusable="false"><rect x="42" y="42" width="336" height="336" class="sg-board-base"/>${grid.join('')}${body}<rect x="42" y="42" width="336" height="336" class="sg-board-outline"/>${txt(210,24,b.n+'″',b.n+'인치')}<text x="18" y="210" text-anchor="middle" transform="rotate(-90 18 210)" data-i18n-en="${b.n}″" data-i18n-ko="${b.n}인치">${b.n}″</text>${ticks.join('')}${txt(210,420,'Inches · grid: 6″','인치 · 격자 한 칸: 6인치','class="sg-ruler"')}</svg>`;}
const centre=()=>'<path d="M204 210h12m-6-6v12" class="sg-centre"/>';
function turfStage(key='both',inches=36){const c=turfCases[key]||turfCases.both,b=board(inches),r=9*b.scale,pos=(dx,dy,side,ignored)=>token(b.cx+dx*b.scale,b.cy+dy*b.scale,side,ignored),inside=[...Array(c.a)].map((_,i)=>pos(-3,-3+i*5,'A')).join('')+[...Array(c.b)].map((_,i)=>pos(4,3-i*5,'B')).join('')+(c.ignored?pos(4,3,'B',true):'');return `<div class="sg-turf-stage">${frame(`<circle cx="210" cy="210" r="${r}" class="sg-zone" data-sg-radius-inches="9"/>${measuredLine(210,210,210+r,210,'9″')}${centre()}${txt(210,233,'Centre','중심')}${inside}${token(b.at(3),b.at(3),'A')}${token(b.at(b.n-3),b.at(b.n-3),'B')}`,b.n)}<div class="sg-counts"><span class="sg-a">A: ${c.a}</span><span class="sg-b">B: ${c.b}</span>${c.ignored?L('× = ignored','× = 판정 제외'):''}<span>${L('Round','라운드')} ${c.round}</span></div><div class="sg-outcome ${c.a&&c.b===0&&c.round>=3||c.b&&c.a===0&&c.round>=3?'is-win':''}" aria-live="polite">${L(...c.result,'strong')}${P(c.why)}</div></div>`;}
function turf(inches=36,key='both'){return `<div class="sg-turf" data-sg-active-case="${E(key)}"><h4>${L('Change the example','상황을 눌러 비교해 보세요')}</h4><div class="sg-cases" role="group" aria-label="Turf War examples" data-i18n-en-aria-label="Turf War examples" data-i18n-ko-aria-label="터프 워 상황 예시">${Object.entries(turfCases).map(([k,c])=>`<button type="button" data-sg-case="${k}" aria-pressed="${k===key}">${L(...c.label)}</button>`).join('')}</div><div data-sg-stage>${turfStage(key,inches)}</div><p class="sg-caption">${L('Central circle: radius 9 inches, diameter 18, on either board size. Both sides also have one model outside the circle in every example. Model symbols are illustrative, not base sizes.','중앙 원은 두 맵 모두 반경 9인치·지름 18인치입니다. 모든 예시에서 양쪽 모두 원 밖에도 모델 1개씩 남아 있습니다. 모델 기호는 실제 베이스 크기를 나타내지 않습니다.')}</p><div class="sg-legend"><span class="sg-a">● A</span><span class="sg-b">■ B</span>${L('× Seriously Injured / Seriously Damaged: ignore','× 중상·중손상: 제외')}</div></div>`;}
function placement(g,inches=36){const b=board(inches);let body='',caption;
 if(g.diagram==='opposite-zones'){const depth=b.n/2-g.gap,h=depth*b.scale,top=210-g.gap*b.scale,bottom=210+g.gap*b.scale;body=`<rect x="42" y="42" width="336" height="${h}" class="sg-fill-a" data-sg-depth-inches="${depth}"/><rect x="42" y="${bottom}" width="336" height="${h}" class="sg-fill-b" data-sg-depth-inches="${depth}"/><path d="M42 210h336M42 ${top}h336M42 ${bottom}h336" class="sg-dash"/>${txt(210,42+h/2+5,'A deployment','A 배치 구역')}${txt(210,bottom+h/2+5,'B deployment','B 배치 구역')}<path d="M85 ${top}v${g.gap*b.scale}" class="sg-distance"/>${txt(118,(top+210)/2+5,g.gap+'″',g.gap+'″')}${txt(270,203,'Central line','중앙선')}${txt(210,245,'No deployment','배치 제외 구간')}`;caption=[`Each boundary is ${g.gap} inches from the centre line. Each zone is ${depth} inches deep on this ${b.n}-inch board; the gap remains ${g.gap*2} inches.`,`중앙선에서 경계까지 각각 ${g.gap}인치입니다. ${b.n}인치 맵에서 각 배치 구역의 깊이는 ${depth}인치이며, 두 경계 사이 간격은 ${g.gap*2}인치입니다.`];}
 else if(g.diagram==='ambush'){const r6=6*b.scale,r12=12*b.scale;body=`<rect x="42" y="42" width="336" height="336" class="sg-fill-a"/><circle cx="210" cy="210" r="${r12}" class="sg-exclusion" data-sg-radius-inches="12"/><circle cx="210" cy="210" r="${r6}" class="sg-fill-b" data-sg-radius-inches="6"/><circle cx="210" cy="210" r="${r12}" class="sg-dash"/>${centre()}${txt(210,196,'Defender','방어자')}${txt(210,234,'Within 6″','6인치 이내')}${txt(210,210-r12-10,'12″ boundary','12인치 경계')}${txt(210,360,'Attacker: ≥12″','공격자: 12인치 이상')}`;caption=['Defender: within the inner 6-inch circle. Attacker: at least 12 inches from the centre. The ring in between is not a deployment zone.','방어자는 중심 6인치 이내, 공격자는 중심에서 12인치 이상 떨어진 곳입니다. 두 원 사이 띠는 어느 쪽 배치 구역도 아닙니다.'];}
 else if(g.diagram==='quarters'){const r=9*b.scale;body=`<rect x="42" y="42" width="168" height="168" class="sg-fill-a"/><rect x="210" y="210" width="168" height="168" class="sg-fill-b"/><path d="M210 42v336M42 210h336" class="sg-dash"/><circle cx="210" cy="210" r="${r}" class="sg-exclusion" data-sg-radius-inches="9"/>${centre()}${txt(110,88,'A quarter','A 사분면')}${txt(310,346,'B quarter','B 사분면')}${measuredLine(210,210,210+r,210,'9″')}${txt(210,238,'Keep outside','원 바깥에 배치')}`;caption=['Example: upper-left versus lower-right quarters. Stay at least 9 inches from the centre, even within your own quarter. The radius is still 9 inches on either map.','왼쪽 위와 오른쪽 아래를 택한 예시입니다. 자기 사분면이어도 중심에서 최소 9인치를 띄웁니다. 두 맵 모두 제외 원의 반경은 9인치입니다.'];}
 else{const r=9*b.scale;body=`<path d="M42 42h${r}a${r} ${r} 0 0 1-${r} ${r}Z M378 378h-${r}a${r} ${r} 0 0 1 ${r}-${r}Z" class="sg-fill-a" data-sg-radius-inches="9"/><path d="M378 42v${r}a${r} ${r} 0 0 1-${r}-${r}Z M42 378v-${r}a${r} ${r} 0 0 1 ${r} ${r}Z" class="sg-fill-b" data-sg-radius-inches="9"/>${txt(65,68,'A','A')}${txt(354,357,'A','A')}${txt(354,68,'B','B')}${txt(65,357,'B','B')}${measuredLine(42,42,42+r,42,'9″')}${txt(210,200,'Each corner: radius 9″','각 모서리: 반경 9인치')}${txt(210,226,'Split the crew evenly','크루를 균등 배분')}`;caption=['A uses one diagonal pair; B uses the other. Measure the 9-inch radius from each corner, not from the centre.','A는 대각선 한 쌍, B는 나머지 한 쌍입니다. 전장 중심이 아니라 각 모서리를 기준으로 반경 9인치를 잽니다.'];}
 return `<figure class="sg-figure">${frame(body,b.n)}<figcaption>${L(...caption)}</figcaption></figure>`;}
function objectives(g,inches=36){const b=board(inches),dot=(x,y,label,side='a')=>`<g class="sg-objective sg-side-${side}" data-sg-x-inches="${x}" data-sg-y-inches="${y}"><circle cx="${b.at(x)}" cy="${b.at(y)}" r="13"/><text x="${b.at(x)}" y="${b.at(y)+5}" text-anchor="middle" data-i18n-ignore>${label}</text></g>`;let body='',caption;
 if(g.diagram==='one-objective'){body=dot(b.n/2,b.n/2,'1')+txt(210,252,'Central objective','중앙 목표');caption=['One central objective. Control at the End-phase check: +1 VP; win at 3 VP.','중앙 목표 1개를 종료 단계 승리 확인 때 통제하면 +1VP, 먼저 3VP면 승리합니다.'];}
 else if(g.diagram==='three-objectives'){body=dot(b.n/2,b.n/2,'1')+dot(9,9,'2')+dot(b.n-9,b.n-9,'3')+txt(210,350,'Control 2 → +1 VP','2개 통제 → +1VP');caption=['The two additional positions are examples. Keep at least 6 inches between objectives and from edges on either map. Marker sizes are illustrative.','추가 목표 두 곳의 위치는 예시입니다. 두 맵 모두 목표끼리와 가장자리에서 최소 6인치를 띄웁니다. 마커 그림은 실제 크기가 아닙니다.'];}
 else if(g.diagram==='opposite-objectives'){const y=b.at(6);body=dot(b.n/2,6,'1')+dot(b.n/2,b.n-6,'2')+`<path d="M250 42v${6*b.scale}M250 ${b.at(b.n-6)}v${6*b.scale}" class="sg-distance"/>`+txt(280,(42+y)/2+5,'6″','6인치')+txt(280,(b.at(b.n-6)+378)/2+5,'6″','6인치')+txt(210,200,'Control both','둘 다 통제')+txt(210,226,'+1 VP','+1VP');caption=['Both objectives are 6 inches inward from opposite edge midpoints. This distance stays 6 inches when the board size changes.','서로 반대편 가장자리 중앙에서 각각 안쪽 6인치에 목표를 놓습니다. 맵 크기를 바꿔도 가장자리와의 거리는 6인치입니다.'];}
 else{body=`<rect x="42" y="42" width="336" height="84" class="sg-fill-b"/><rect x="42" y="294" width="336" height="84" class="sg-fill-a"/>`+txt(210,62,'B deployment zone (example)','B 배치 구역 예시')+txt(210,365,'A deployment zone (example)','A 배치 구역 예시')+[b.n/4,b.n/2,b.n*3/4].map(x=>dot(x,b.n/8,'A','a')+dot(x,b.n*7/8,'B','b')).join('')+txt(210,200,'Control → remove → +1 VP','통제 → 제거 → +1VP')+txt(210,226,'Win at 2 VP','목표 2VP');caption=['A places three objectives in B’s zone; B places three in A’s. Zone shapes and positions are examples, not a deployment prescribed by this objective. Use the separately selected deployment; keep markers 6 inches apart if possible.','A는 B 구역에 3개, B는 A 구역에 3개를 놓습니다. 배치 구역과 위치는 예시이며 이 목표가 배치 형태를 정하는 것은 아닙니다. 별도로 고른 배치를 사용하고 가능하면 목표끼리 6인치를 띄우세요.'];}
 return `<figure class="sg-figure">${frame(body,b.n)}<figcaption>${L(...caption)}</figcaption></figure>`;}
function spatial(g,inches=36,key='both'){return g.diagram==='turf'?turf(inches,key):g.diagram.endsWith('objective')||g.diagram.endsWith('objectives')?objectives(g,inches):placement(g,inches);}
function mapView(g,key){return `<div class="sg-map-view" data-sg-map-key="${E(key)}" data-sg-map-size="36"><div class="sg-size-control"><strong>${L('Diagram board size','도식 기준 맵 크기')}</strong><div class="sg-size-buttons" role="group" aria-label="Diagram board size" data-i18n-en-aria-label="Diagram board size" data-i18n-ko-aria-label="도식 기준 맵 크기">${[36,48].map(n=>`<button type="button" data-sg-size="${n}" aria-pressed="${n===36}">${L(n/12+' × '+n/12+' ft',n/12+' × '+n/12+'피트')}<small data-i18n-ignore>${n}″ × ${n}″</small></button>`).join('')}</div><p class="sg-size-status" aria-live="polite" data-sg-size-status>${sizeStatus(36)}</p></div><div data-sg-map-drawing>${spatial(g,36)}</div><p class="sg-caption sg-scale-note">${L('Board areas and fixed distances are drawn to scale. Decide your actual battlefield size together; switching this diagram does not change fixed rule distances.','전장 구역과 고정 거리를 실제 비율로 표시합니다. 사용할 전장 크기는 상대와 정하세요. 도식을 전환해도 규칙의 고정 거리는 바뀌지 않습니다.')}</p></div>`;}
function sizeStatus(n){return L(`Viewing ${n/12} × ${n/12} ft · ${n} × ${n} inches`,`현재 ${n/12} × ${n/12}피트 · ${n} × ${n}인치 기준`);}
function crew(g){const c=g.crew,formula=(chosen,random,label)=>`<div class="sg-formula"><h4>${L(...label)}</h4><div class="sg-number-flow"><div>${L('Choose','직접 선택','small')}<b>${chosen}</b></div>${random?`<span aria-hidden="true">+</span><div>${L('Random','무작위','small')}<b>${random}</b></div>`:''}<span aria-hidden="true">→</span><div>${L('Starting crew','시작 크루','small')}<b>${typeof chosen==='number'&&typeof random==='number'?chosen+random:chosen+(random?' + '+random:'')}</b></div></div></div>`;return formula(c.chosen,c.random,c.defender?['Attacker','공격자']:['Both players','양쪽 플레이어'])+(c.defender?formula(3,0,['Defender','방어자']):'')+(c.deck?`<div class="sg-note">${L('Separate reinforcement deck','별도 증원 덱','strong')}<p>${c.deck} ${L('cards · D3 per End phase from round 1','장 · 1라운드부터 매 종료 단계 D3명')}</p></div>`:'');}
function formula(){return `<div class="sg-number-flow sg-vp-formula"><div>${L('Enemy OOA','적 OOA','small')}<b>1</b></div><span>+</span><div>${L('Leader / Champion / Brute','리더·챔피언·브루트','small')}<b>1</b></div><span>+</span><div>${L('Fight / Coup de Grace / Sabotage','파이트·쿠 드 그라스·사보타주','small')}<b>1</b></div><span>=</span><div><small>VP</small><b>3</b></div></div><p class="sg-caption">${L('Example where both bonuses apply. A missing bonus is 0.','두 보너스가 모두 적용되는 예시입니다. 해당하지 않는 보너스는 0으로 계산합니다.')}</p>`;}
function markup(row,kind,options={}){const found=resolve(row,kind,options);if(!found)return '';const {source,key,guide:g}=found;const visual=g.diagram==='crew'?crew(g):g.diagram==='vp-formula'?formula():g.diagram==='job'?'':mapView(g,key);const links=(g.links||[]).map(id=>(R().coreRules||[]).find(r=>valid(r)&&r.id===id)).filter(Boolean);
 return `<section class="scenario-guide" data-scenario-guide="${E(source.id)}"><p class="sg-eyebrow">${L('See how this mission works','그림과 예시로 이해하기')}</p><div class="sg-summary">${P(g.summary)}</div><div class="sg-layout ${visual?'':'sg-no-visual'}">${visual?`<div class="sg-visual">${visual}</div>`:''}<div class="sg-reading"><h4>${L('Follow this order','이 순서로 진행하세요')}</h4><ol class="sg-steps">${g.steps.map(step=>`<li>${L(...step.title,'strong')}${P(step.body)}</li>`).join('')}</ol>${g.control?`<aside class="sg-note sg-control">${L('What does “control” mean?','‘통제’는 어떻게 확인하나요?','strong')}${P(['Within 3 inches of the objective centre: at least one friendly non-Pet Fighter and no enemy models. Ignore Seriously Injured/Damaged models. Enemy Pets and Vehicles can still contest.','목표 중심 3인치 안에 펫이 아닌 아군 파이터가 1명 이상 있고 적 모델이 없어야 합니다. 중상·중손상 모델은 무시하지만 적 펫·차량도 통제를 방해할 수 있습니다.'])}</aside>`:''}<aside class="sg-example">${L('Worked example','실제 상황 예시','strong')}${P(g.example)}</aside>${g.caution?`<p class="sg-caution">${L(...g.caution)}</p>`:''}</div></div>${source.rule_data?.sole_remaining_player_wins?`<aside class="sg-note sg-ending">${L('Also check the whole battlefield','전장 전체의 종료 조건도 확인','strong')}${P(['If only one side has models left on the battlefield, that side wins. If neither side has models, draw. This is separate from the central area or objective count.','전장에 한쪽 모델만 남으면 그쪽이 승리하고 양쪽 모두 없으면 무승부입니다. 중앙 원이나 목표 주변의 모델 수와 전장 전체의 잔존 모델 수를 구분하세요.'])}</aside>`:''}${links.length?`<nav class="sg-links">${L('Related rules','관련 판정 규칙','strong')}${links.map(r=>`<button type="button" class="btn small" data-sg-rule="${E(r.id)}">${L(r.name,r.name_ko||r.name)}</button>`).join('')}</nav>`:''}<p class="sg-caption">${L('Examples explain the rule; they do not record a win, VP or rewards.','이 화면은 설명용 예시입니다. 승패·VP·보상을 기록하지 않습니다.')}</p></section>`;
}
window.addEventListener('click',e=>{
 const button=e.target.closest?.('[data-sg-case],[data-sg-rule],[data-sg-size]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();
 if(button.dataset.sgRule)return window.MMRuleReference?.open('coreRules',button.dataset.sgRule,{edition:'n26',activator:button,nested:true});
 const map=button.closest('.sg-map-view'),inches=boardSize(map?.dataset.sgMapSize);
 if(button.hasAttribute('data-sg-size')){
  if(!map||!['36','48'].includes(button.dataset.sgSize))return;
  const source=(R().scenarioEntries||[]).find(r=>r.id==='official-003-scenario-entry-'+map.dataset.sgMapKey),found=resolve(source,'scenarioEntries',{edition:'n26'});if(!found)return;
  const next=boardSize(button.dataset.sgSize),key=map.querySelector('.sg-turf')?.dataset.sgActiveCase||'both';map.dataset.sgMapSize=String(next);
  map.querySelectorAll('[data-sg-size]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.sgSize===String(next))));
  map.querySelector('[data-sg-size-status]').innerHTML=sizeStatus(next);map.querySelector('[data-sg-map-drawing]').innerHTML=spatial(found.guide,next,key);window.UKI18n?.refresh(map);return;
 }
 const root=button.closest('.sg-turf'),key=button.dataset.sgCase;if(!root||!turfCases[key])return;root.dataset.sgActiveCase=key;root.querySelectorAll('[data-sg-case]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));root.querySelector('[data-sg-stage]').innerHTML=turfStage(key,inches);window.UKI18n?.refresh(root);
},true);
window.MMScenarioGuide={markup,resolve};
})();
